using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class GeneratedFormatterEdgeCaseTests
{
    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    private static async Task<ImmutableArray<MetadataReference>> GetReferencesAsync()
    {
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        return framework.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
    }

    private static async Task<(string? FormatterSource, Compilation Output, ImmutableArray<Diagnostic> GeneratorDiagnostics)> RunAsync(string source, params MetadataReference[] extra)
    {
        ImmutableArray<MetadataReference> refs = (await GetReferencesAsync()).AddRange(extra);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ProjectB",
            new[] { CSharpSyntaxTree.ParseText(source, ParseOptions) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: ParseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);
        string? formatter = driver.GetRunResult().GeneratedTrees
            .Select(t => t.GetText().ToString())
            .FirstOrDefault(t => t.Contains("partial class ThirdPartyFormatter"));
        return (formatter, output, generatorDiagnostics);
    }

    [Fact]
    public async Task IgnoreMemberOnFormattedTypeIsHonoured()
    {
        string source = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                public class MyType
                {
                    public int Visible { get; set; }

                    [IgnoreMember]
                    public int Secret { get; set; }
                }

                [GeneratedMessagePackFormatter]
                public partial class ThirdPartyFormatter : IMessagePackFormatter<MyType> { }

                [GeneratedMessagePackResolver]
                partial class MyResolver { }
            }
            """;

        var (formatterSource, _, _) = await RunAsync(source);
        formatterSource.Should().NotBeNull("a formatter body should be generated for ThirdPartyFormatter");
        formatterSource.Should().NotContain("Secret", "a member marked [IgnoreMember] on T must not be serialized");
    }

    [Fact]
    public async Task KeyAttributesOnReferencedTypeAreHonoured()
    {
        string projectA = """
            using MessagePack;

            namespace ProjectA
            {
                [MessagePackObject]
                public class MyType
                {
                    [Key(0)]
                    public int Alpha { get; set; }

                    [Key(1)]
                    public string Beta { get; set; }
                }
            }
            """;
        CSharpCompilation a = CSharpCompilation.Create(
            "ProjectA",
            new[] { CSharpSyntaxTree.ParseText(projectA, ParseOptions) },
            await GetReferencesAsync(),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using MemoryStream stream = new();
        var emitResult = a.Emit(stream);
        emitResult.Success.Should().BeTrue(string.Join(Environment.NewLine, emitResult.Diagnostics));
        MetadataReference aRef = MetadataReference.CreateFromImage(stream.ToArray());

        string source = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [GeneratedMessagePackFormatter]
                public partial class ThirdPartyFormatter : IMessagePackFormatter<ProjectA.MyType> { }

                [GeneratedMessagePackResolver]
                partial class MyResolver { }
            }
            """;

        var (formatterSource, _, _) = await RunAsync(source, aRef);
        formatterSource.Should().NotBeNull("a formatter body should be generated for ThirdPartyFormatter");
        formatterSource.Should().NotContain("WriteMapHeader", "T declares integer [Key] attributes, so the array (int key) contract must be honoured");
    }

    [Fact]
    public async Task NestedFormatterInNonPartialTypeIsDiagnosedOrCompiles()
    {
        string source = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                public class MyType
                {
                    public int Visible { get; set; }
                }

                public static class Formatters
                {
                    [GeneratedMessagePackFormatter]
                    public partial class ThirdPartyFormatter : IMessagePackFormatter<MyType> { }
                }

                [GeneratedMessagePackResolver]
                partial class MyResolver { }
            }
            """;

        var (_, output, generatorDiagnostics) = await RunAsync(source);
        bool generatorReportedError = generatorDiagnostics.Any(d => d.Severity == DiagnosticSeverity.Error);
        List<Diagnostic> compileErrors = output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
        (generatorReportedError || compileErrors.Count == 0).Should().BeTrue(
            "either the generator must reject the formatter with a diagnostic or the generated code must compile, but got: " + string.Join(Environment.NewLine, compileErrors));
    }
}
